// Edit here: SerpApi keys, keywords, output sheet, and your app's App Store ID.
// Disable a group with enabled: false. Do not comment out GROUPS entries — use enabled instead.

const SETTINGS = {
  spreadsheetId: 'YOUR_GOOGLE_SHEET_ID',
  positionSheetName: 'position',
  appStoreAppId: 1234567890,
  country: 'us',
  lang: 'en-us',
  resultsNum: 100,
};

const GROUPS = [
  {
    group: 'group1',
    enabled: true,
    apiKey: 'PASTE_SERPAPI_KEY_GROUP1',
    words:
      'wardrobe app, outfit planner, closet organizer, style assistant, fashion app, try on clothes, outfit ideas',
  },
  {
    group: 'group2',
    enabled: false,
    apiKey: 'PASTE_SERPAPI_KEY_GROUP2',
    words:
      'capsule wardrobe, lookbook app, personal stylist, what to wear, clothing combinations, daily outfits',
  },
  {
    group: 'group3',
    enabled: false,
    apiKey: 'PASTE_SERPAPI_KEY_GROUP3',
    words:
      'shopping list fashion, wardrobe planner, mix and match outfits, dress code helper, seasonal trends',
  },
];

function splitWords(raw) {
  return String(raw ?? '')
    .split(/[,;\n]+/)
    .map((s) => s.trim())
    .filter(Boolean);
}

const items = [];

for (const cfg of GROUPS) {
  if (!cfg.enabled) continue;

  const group = cfg.group;
  const apiKey = String(cfg.apiKey ?? '').trim();
  const keywords = splitWords(cfg.words);

  if (!keywords.length) continue;

  if (!apiKey || apiKey.startsWith('PASTE_')) {
    throw new Error(
      `${group}: set apiKey (replace PASTE_...) or set enabled: false.`,
    );
  }

  if (String(SETTINGS.spreadsheetId).includes('YOUR_GOOGLE')) {
    throw new Error('Set SETTINGS.spreadsheetId to your Google Sheet ID.');
  }

  for (const keyword of keywords) {
    items.push({
      json: {
        group,
        keyword,
        serpApiKey: apiKey,
        ...SETTINGS,
      },
    });
  }
}

if (!items.length) {
  throw new Error('No keywords queued — enable a group and add keywords in GROUPS.');
}

return items;

const loop = $('Loop keywords').item.json;
const { keyword, group, appStoreAppId, resultsNum } = loop;
const appId = Number(appStoreAppId);
const maxResults = Number(resultsNum) || 100;

const raw = $input.first().json;
const date = $now.toFormat('yyyy-MM-dd');

const sheetFields = {
  spreadsheetId: loop.spreadsheetId,
  positionSheetName: loop.positionSheetName,
};

if (raw.error) {
  return [{
    json: {
      keyword,
      group,
      position: 'ERROR',
      apps: '',
      date,
      error: String(raw.error),
      ...sheetFields,
    },
  }];
}

const results = raw.organic_results || [];
const hit = results.find((a) => Number(a.id) === appId);
const apps = raw.search_information?.results_count ?? results.length;

return [{
  json: {
    keyword,
    group,
    position: hit ? hit.position : '>' + maxResults,
    apps,
    date,
    ...sheetFields,
  },
}];
